#!/usr/bin/env bash
# Applied by "cka verify". Generated by Quick Create.
set -euo pipefail

# Question 1: Hardening review of ${Q1_NS}-apps
kubectl -n ${Q1_NS}-apps get pods -o json | jq -r '.items[] | select([((.spec.initContainers // []) + .spec.containers)[] | .securityContext.privileged // false] | any) | .metadata.name' > /opt/course/audit/privileged.txt
kubectl -n ${Q1_NS}-apps get pods -o json | jq -r '.items[] | select(.spec.hostNetwork == true) | .metadata.name' > /opt/course/audit/host-network.txt
kubectl -n ${Q1_NS}-apps get pods -o json | jq -r '.items[] | select([.spec.volumes[]? | has("hostPath")] | any) | .metadata.name' > /opt/course/audit/host-path.txt

# Question 2: Resource review of ${Q2_NS}-compute
kubectl -n ${Q2_NS}-compute get pods -o json | jq -r '.items[] | select([.spec.containers[].resources.limits.memory] | any(. == null)) | .metadata.name' > /opt/course/audit/no-memory-limit.txt
kubectl -n ${Q2_NS}-compute get pods -o json | jq -r '[.items[] | {n: .metadata.name, m: ([.spec.containers[].resources.requests.cpu // "0m" | rtrimstr("m") | tonumber] | add)}] | sort_by(-.m) | .[:3][] | .n' > /opt/course/audit/top-cpu.txt

# Question 3: Unhealthy Pods in ${Q3_NS}-ops
kubectl -n ${Q3_NS}-ops get pods -o json | jq -r '.items[] | select(.status.phase != "Succeeded") | select(([.status.conditions[]? | select(.type == "Ready") | .status] | first) != "True") | .metadata.name' > /opt/course/audit/unhealthy.txt
kubectl -n ${Q3_NS}-ops get pods -o json | jq -r '.items[] | select([.status.conditions[]? | select(.type == "PodScheduled" and .status == "False")] | length > 0) | .metadata.name' > /opt/course/audit/unscheduled.txt
kubectl -n ${Q3_NS}-ops get pods -o json | jq -r '.items[] | select([.status.containerStatuses[]? | .state.waiting.reason // ""] | any(test("ErrImagePull|ImagePullBackOff"))) | .spec.containers[].image' | sort -u > /opt/course/audit/bad-image.txt

# Question 4: Leftovers in ${Q4_NS}-svc
for s in $(kubectl -n ${Q4_NS}-svc get services -o json | jq -r '.items[] | select(.spec.selector) | .metadata.name + "=" + (.spec.selector | to_entries | map("\(.key)=\(.value)") | join(","))'); do if [ -z "$(kubectl -n ${Q4_NS}-svc get pods -l "${s#*=}" -o name)" ]; then echo "${s%%=*}"; fi; done > /opt/course/audit/empty-services.txt
{ used=$(kubectl -n ${Q4_NS}-svc get pods -o json | jq -r '.items[].spec.serviceAccountName' | sort -u); kubectl -n ${Q4_NS}-svc get serviceaccounts -o jsonpath='{range .items[*]}{.metadata.name}{"\n"}{end}' | grep -vx default | grep -vxF "$used" || true; } > /opt/course/audit/unused-serviceaccounts.txt

# Question 5: Ingress routes of ${Q5_NS}
kubectl get ingress -A -o json | jq -r --arg p "${Q5_NS}-" '.items[] | select(.metadata.namespace | startswith($p)) | .spec.rules[] as $r | $r.http.paths[] | "\($r.host) \(.path) \(.backend.service.name):\(.backend.service.port.number // .backend.service.port.name)"' > /opt/course/audit/ingress-rules.txt
kubectl get ingress -A -o json | jq -r --arg p "${Q5_NS}-" '.items[] | select(.metadata.namespace | startswith($p)) | .metadata.namespace as $ns | .spec.rules[].http.paths[].backend.service.name | $ns + " " + .' | sort -u | while read -r ns svc; do kubectl -n "$ns" get service "$svc" >/dev/null 2>&1 || echo "$ns/$svc"; done > /opt/course/audit/missing-backends.txt
